class TestSecureMeshDeserializer:
    """Security-critical deserialization validation."""

    def test_valid_raw_message_deserializes(self, valid_message_payload):
        raw = orjson.dumps(valid_message_payload)
        deserializer = SecureMeshDeserializer()
        result = deserializer.deserialize(raw)
        assert result.sender_id == "agent-alpha"

    def test_raw_size_limit_enforced(self, valid_message_payload):
        oversized = b"x" * (MAX_RAW_MESSAGE_SIZE + 1)
        deserializer = SecureMeshDeserializer()
        with pytest.raises(ValueError, match="raw message size"):
            deserializer.deserialize(oversized)

    def test_malformed_json_rejected(self):
        deserializer = SecureMeshDeserializer()
        with pytest.raises(ValueError, match="invalid JSON"):
            deserializer.deserialize(b"{not valid json")

    def test_payload_size_limit_enforced(self, valid_message_payload):
        valid_message_payload["payload"] = {"data": "y" * (MAX_PAYLOAD_SIZE + 1)}
        raw = orjson.dumps(valid_message_payload)
        deserializer = SecureMeshDeserializer()
        with pytest.raises(ValueError, match="payload size"):
            deserializer.deserialize(raw)

    def test_timestamp_bounds_enforced(self, valid_message_payload):
        old_timestamp = datetime.now(timezone.utc) - timedelta(hours=2)
        valid_message_payload["timestamp"] = old_timestamp.isoformat()
        raw = orjson.dumps(valid_message_payload)
        deserializer = SecureMeshDeserializer(max_age_seconds=3600)
        with pytest.raises(ValueError, match="timestamp"):
            deserializer.deserialize(raw)

    def test_hmac_verification_success(self, valid_message_payload, hmac_secret):
        raw = orjson.dumps(valid_message_payload)
        signature = hmac.new(
            hmac_secret, raw, hashlib.sha256
        ).hexdigest()
        deserializer = SecureMeshDeserializer(hmac_secret=hmac_secret)
        result = deserializer.deserialize(raw, signature=signature)
        assert result.sender_id == "agent-alpha"

    def test_hmac_verification_failure(self, valid_message_payload, hmac_secret):
        raw = orjson.dumps(valid_message_payload)
        wrong_signature = "0" * 64
        deserializer = SecureMeshDeserializer(hmac_secret=hmac_secret)
        with pytest.raises(ValueError, match="signature"):
            deserializer.deserialize(raw, signature=wrong_signature)

    def test_missing_signature_when_required(self, valid_message_payload, hmac_secret):
        raw = orjson.dumps(valid_message_payload)
        deserializer = SecureMeshDeserializer(hmac_secret=hmac_secret, require_signature=True)
        with pytest.raises(ValueError, match="signature"):
            deserializer.deserialize(raw)

    def test_replay_attack_detected(self, valid_message_payload, hmac_secret):
        raw = orjson.dumps(valid_message_payload)
        signature = hmac.new(hmac_secret, raw, hashlib.sha256).hexdigest()
        deserializer = SecureMeshDeserializer(hmac_secret=hmac_secret)
        # First deserialization succeeds
        deserializer.deserialize(raw, signature=signature)
        # Replay should be rejected
        with pytest.raises(ValueError, match="replay"):
            deserializer.deserialize(raw, signature=signature)


