class TestFaultTolerance:
    """Chaos engineering: system resilience under failure."""

    @pytest.mark.asyncio
    async def test_mesh_survives_partial_node_failure(self, mesh_instance):
        # Register 5 nodes
        for i in range(5):
            await mesh_instance.register_node(node_id=f"agent-{i}")

        # Kill 3 nodes abruptly
        for i in range(3):
            mesh_instance.nodes.pop(f"agent-{i}", None)

        # Remaining nodes should still function
        remaining = await mesh_instance.list_active_nodes()
        assert len(remaining) == 2

    @pytest.mark.asyncio
    async def test_corrupt_message_handled_gracefully(self, mesh_instance):
        await mesh_instance.register_node(node_id="agent-1")
        corrupt_raw = b"\x00\x01\x02corrupt"
        result = await mesh_instance.process_incoming_message(corrupt_raw)
        assert result["status"] == "rejected"
        assert "error" in result

    @pytest.mark.asyncio
    async def test_high_concurrency_registration(self, mesh_instance):
        """Stress test: 100 concurrent registrations."""
        async def register(i):
            await mesh_instance.register_node(node_id=f"agent-{i}")

        await asyncio.gather(*[register(i) for i in range(100)])
        assert len(mesh_instance.nodes) == 100

    @pytest.mark.asyncio
    async def test_rapid_route_task_throughput(self, mesh_instance):
        await mesh_instance.register_node(node_id="agent-1")
        await mesh_instance.register_node(node_id="agent-2")

        async def route_task(i):
            return await mesh_instance.route_task(
                task={"id": i, "type": "compute"},
                target_node="agent-2",
            )

        results = await asyncio.gather(*[route_task(i) for i in range(50)])
        assert all(r["status"] == "routed" for r in results)


