from hypothesis import given, strategies as st

class TestPropertyBased:
    """Property-based validation of core invariants."""

    @given(
        sender=st.text(min_size=1, max_size=50),
        receiver=st.text(min_size=1, max_size=50),
        msg_type=st.sampled_from(["task_request", "task_response", "heartbeat", "discovery"]),
        payload=st.dictionaries(st.text(), st.integers(), max_size=10),
    )
    def test_message_roundtrip_property(self, sender, receiver, msg_type, payload):
        """Any valid message should serialize/deserialize without loss."""
        msg = MeshMessage(
            sender_id=sender,
            receiver_id=receiver,
            message_type=msg_type,
            payload=payload,
            timestamp=datetime.now(timezone.utc).isoformat(),
            correlation_id=f"corr-{hash((sender, receiver, time.time()))}",
            ttl_seconds=300,
        )
        raw = orjson.dumps(msg.model_dump())
        deserializer = SecureMeshDeserializer()
        result = deserializer.deserialize(raw)
        assert result.sender_id == sender
        assert result.payload == payload

    @given(
        data=st.binary(max_size=MAX_RAW_MESSAGE_SIZE),
    )
    def test_deserializer_never_crashes_on_arbitrary_bytes(self, data):
        """Deserializer must handle any input without crashing."""
        deserializer = SecureMeshDeserializer()
        try:
            deserializer.deserialize(data)
        except (ValueError, ValidationError):
            pass  # Expected for invalid data
        # No exception means it was valid, which is fine

    @given(
        node_ids=st.lists(st.text(min_size=1, max_size=20), min_size=1, max_size=10),
    )
    @pytest.mark.asyncio
    async def test_mesh_registration_idempotent_property(self, node_ids):
        """Registering same node multiple times should not corrupt state."""
        mesh = AgentMesh(node_id="prop-test", storage_path="/tmp/prop-mesh")
        for nid in node_ids:
            try:
                await mesh.register_node(node_id=nid)
            except ValueError:
                pass  # Duplicate, expected
        # After all registrations, each unique node appears exactly once
        unique_ids = set(node_ids)
        assert len(mesh.nodes) == len(unique_ids)


