class TestIntegration:
    """Full mesh lifecycle integration test."""

    @pytest.mark.asyncio
    async def test_full_mesh_lifecycle(self, tmp_path):
        """Complete workflow: registration → discovery → routing → gossip → cleanup."""
        mesh = AgentMesh(
            node_id="integration-mesh",
            storage_path=str(tmp_path / "integration"),
            gossip_interval=0.05,
            heartbeat_timeout=0.3,
        )

        # Phase 1: Registration
        await mesh.register_node(node_id="worker-1", capabilities={"compute"})
        await mesh.register_node(node_id="worker-2", capabilities={"compute", "storage"})
        await mesh.register_node(node_id="worker-3", capabilities={"vision"})

        # Phase 2: Discovery
        compute_workers = await mesh.discover_peers(capability="compute")
        assert len(compute_workers) == 2

        # Phase 3: Task routing
        result = await mesh.route_task(
            task={"type": "compute", "data": [1, 2, 3]},
            target_node="worker-2",
        )
        assert result["status"] == "routed"

        # Phase 4: Gossip convergence
        gossip_task = asyncio.create_task(mesh.start_gossip())
        await asyncio.sleep(0.2)

        # Phase 5: Node failure & recovery
        mesh.nodes["worker-1"].last_heartbeat = time.time() - 10
        await mesh.prune_expired_nodes()
        assert "worker-1" not in mesh.nodes

        # Phase 6: Cleanup
        await mesh.shutdown()
        gossip_task.cancel()
        with pytest.raises(asyncio.CancelledError):
            await gossip_task

    @pytest.mark.asyncio
    async def test_secure_message_flow_with_hmac(self, tmp_path, hmac_secret):
        """End-to-end secure message exchange with HMAC."""
        mesh = AgentMesh(
            node_id="secure-mesh",
            storage_path=str(tmp_path / "secure"),
            hmac_secret=hmac_secret,
        )

        await mesh.register_node(node_id="sender")
        await mesh.register_node(node_id="receiver")

        # Create and sign a message
        msg = MeshMessage(
            sender_id="sender",
            receiver_id="receiver",
            message_type="task_request",
            payload={"task": "secure_compute"},
            timestamp=datetime.now(timezone.utc).isoformat(),
            correlation_id="corr-secure-1",
            ttl_seconds=300,
        )
        raw = orjson.dumps(msg.model_dump())
        signature = hmac.new(hmac_secret, raw, hashlib.sha256).hexdigest()

        # Send with signature
        result = await mesh.send_secure_message(raw, signature)
        assert result["status"] == "delivered"

        # Tampered message should be rejected
        tampered = raw + b"tamper"
        with pytest.raises(ValueError, match="signature"):
            await mesh.send_secure_message(tampered, signature)


