class TestSecurityRegression:
    """Security invariants that must never regress."""

    def test_no_plaintext_secrets_in_logs(self, caplog):
        """Ensure secrets never appear in log output."""
        import logging
        caplog.set_level(logging.DEBUG)

        verifier = MeshSignatureVerifier(secret=b"super-secret-value")
        verifier.sign(b"data")

        # Check all log records for secret leakage
        for record in caplog.records:
            assert "super-secret-value" not in record.getMessage()

    def test_mesh_dir_permissions(self, tmp_path):
        """Mesh directory should have restrictive permissions."""
        mesh = AgentMesh(node_id="perm-test", storage_path=str(tmp_path / "mesh"))
        mesh_dir = tmp_path / "mesh"
        assert mesh_dir.exists()
        # Check POSIX permissions (0o700 or stricter)
        mode = os.stat(mesh_dir).st_mode & 0o777
        assert mode <= 0o700, f"Mesh dir too permissive: {oct(mode)}"

    def test_deserializer_rejects_nested_payload_bombs(self):
        """Deeply nested payloads should be rejected."""
        deserializer = SecureMeshDeserializer(max_depth=10)
        deep_payload = {"level": 0}
        for i in range(1, 20):
            deep_payload = {"level": i, "child": deep_payload}

        raw = orjson.dumps({"payload": deep_payload})
        with pytest.raises(ValueError, match="depth"):
            deserializer.deserialize(raw)

    def test_hmac_constant_time_comparison(self, hmac_secret):
        """Signature comparison should be constant-time."""
        verifier = MeshSignatureVerifier(secret=hmac_secret)
        data = b"test"
        valid_sig = verifier.sign(data)
        invalid_sig = b"0" * len(valid_sig)

        # Timing attack resistance: both should take similar time
        import timeit
        valid_time = timeit.timeit(
            lambda: verifier.verify(data, valid_sig), number=1000
        )
        invalid_time = timeit.timeit(
            lambda: verifier.verify(data, invalid_sig), number=1000
        )
        # Allow 30% variance for system noise
        assert abs(valid_time - invalid_time) / max(valid_time, invalid_time) < 0.3


